		}

		for (Map<String, Object> member : members)
		{
			JPanel row = new JPanel(new BorderLayout());
			row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			row.setBorder(new EmptyBorder(5, 6, 5, 6));

			String rsn = stringVal(member, "rsn");
