package net.osrsconquest;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.osrsconquest.model.ClanEvent;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ClanChannelChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

@Slf4j
@PluginDescriptor(
	name = "OSRS Conquest",
	description = "Tracks clan activity, XP gains, and playtime to a shared backend",
	tags = {"clan", "tracker", "stats", "conquest"}
)
public class OSRSConquestPlugin extends Plugin
{
	private static final int PANEL_REFRESH_TICKS = 100;  // ~60 seconds
	private static final int STAT_FLUSH_TICKS = 500;    // ~5 minutes
	private static final int MEMBER_SYNC_TICKS = 500;   // ~5 minutes (keeps online status fresh)
	private static final int INITIAL_SYNC_TICKS = 10;   // ~6 seconds after login

	@Inject
	private Client client;

	@Inject
	private OSRSConquestConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ConquestApiClient apiClient;

	@Inject
	private ClanEventParser eventParser;

	@Inject
	private SessionTracker sessionTracker;

	@Inject
	private StatTracker statTracker;

	@Inject
	private ClanStateManager clanStateManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ApplicationNotificationOverlay applicationOverlay;

	private OSRSConquestPanel panel;
	private NavigationButton navButton;

	private final List<ClanEvent> eventQueue = Collections.synchronizedList(new ArrayList<>());
	private int tickCounter = 0;
	private volatile boolean registrationPending = false;
	private boolean initialSyncDone = false;

	@Override
	protected void startUp()
	{
		panel = injector.getInstance(OSRSConquestPanel.class);
		panel.setSyncMembersCallback(() -> clanStateManager.syncMembers(client));

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/conquest_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("OSRS Conquest")
			.icon(icon != null ? icon : new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB))
			.priority(10)
			.panel(panel)
			.build();

		if (config.showPanel())
		{
			clientToolbar.addNavigation(navButton);
		}

		overlayManager.add(applicationOverlay);

		log.info("OSRS Conquest started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(applicationOverlay);
		clientToolbar.removeNavigation(navButton);
		flushEventQueue();
		log.info("OSRS Conquest stopped");
	}

	@Provides
	OSRSConquestConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OSRSConquestConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			tickCounter = 0;
			initialSyncDone = false;

			if (config.dataConsent())
			{
				int world = client.getWorld();
				sessionTracker.onLogin(world);
				statTracker.captureAndSubmit(client);
			}

			panel.refreshCurrentTab();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			if (config.dataConsent())
			{
				sessionTracker.onLogout();
				flushEventQueue();
			}
		}
	}

	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event)
	{
		if (!config.dataConsent())
		{
			return;
		}

		String detectedClan = clanStateManager.detectClanName(client);

		if (detectedClan != null && !detectedClan.isEmpty())
		{
			// Auto-register if no API key configured
			if (config.apiKey().isEmpty() && !registrationPending)
			{
				registrationPending = true;
				String rsn = client.getLocalPlayer() != null
					? client.getLocalPlayer().getName()
					: null;

				if (rsn != null)
				{
					apiClient.register(rsn, detectedClan,
						(response) -> {
							// Save the API key to config
							configManager.setConfiguration("osrsconquest", "apiKey", response.getApiKey());
							registrationPending = false;
							log.info("Auto-registered with OSRS Conquest as {} in clan {}", rsn, detectedClan);

							// Now that we have a key, refresh panel
							if (config.autoSyncMembers())
							{
								clanStateManager.syncMembers(client);
							}
							panel.refreshCurrentTab();
						},
						(error) -> {
							registrationPending = false;
							log.warn("Auto-registration failed: {}", error);
						}
					);
				}
			}
			else
			{
				// Already registered, sync if opted in and refresh panel
				if (config.autoSyncMembers())
				{
					clanStateManager.syncMembers(client);
				}
				panel.refreshCurrentTab();
			}
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.CLAN_MESSAGE
			&& event.getType() != ChatMessageType.CLAN_GIM_MESSAGE)
		{
			return;
		}

		if (!config.dataConsent() || !config.trackEvents() || config.apiKey().isEmpty())
		{
			return;
		}

		ClanEvent clanEvent = eventParser.parse(event.getMessage());
		if (clanEvent != null)
		{
			eventQueue.add(clanEvent);

			// Show viewport notification for applications
			if ("APPLICATION".equals(clanEvent.getType()))
			{
				applicationOverlay.showNotification(clanEvent.getActor());
			}

			log.debug("Queued clan event: {} by {}", clanEvent.getType(), clanEvent.getActor());

			// Flush immediately for important events
			if ("JOIN".equals(clanEvent.getType())
				|| "LEAVE".equals(clanEvent.getType())
				|| "KICK".equals(clanEvent.getType())
				|| "APPLICATION".equals(clanEvent.getType()))
			{
				flushEventQueue();
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tickCounter++;

		if (!config.dataConsent())
		{
			return;
		}

		// Flush events every 10 ticks (~6 seconds) if any are queued
		if (tickCounter % 10 == 0 && !eventQueue.isEmpty())
		{
			flushEventQueue();
		}

		// Initial sync ~6 seconds after login (gives clan channel time to populate)
		if (!initialSyncDone && tickCounter == INITIAL_SYNC_TICKS)
		{
			initialSyncDone = true;
			if (config.autoSyncMembers())
			{
				clanStateManager.syncMembers(client);
			}
			panel.refreshCurrentTab();
		}

		// Refresh sidebar panel every ~60 seconds
		if (tickCounter % PANEL_REFRESH_TICKS == 0)
		{
			panel.refreshCurrentTab();
		}

		// Submit stats every 5 minutes
		if (tickCounter % STAT_FLUSH_TICKS == 0)
		{
			statTracker.captureAndSubmit(client);
		}

		// Sync members every 5 minutes if user opted in
		if (config.autoSyncMembers() && tickCounter % MEMBER_SYNC_TICKS == 0)
		{
			clanStateManager.syncMembers(client);
		}
	}

	private void flushEventQueue()
	{
		if (eventQueue.isEmpty())
		{
			return;
		}

		List<ClanEvent> toSubmit;
		synchronized (eventQueue)
		{
			toSubmit = new ArrayList<>(eventQueue);
			eventQueue.clear();
		}

		apiClient.submitEvents(toSubmit);
	}
}

package net.osrsconquest;

import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;

@Slf4j
@Singleton
public class SessionTracker
{
	private final ConquestApiClient apiClient;
	private final OSRSConquestConfig config;
	private volatile boolean sessionActive = false;

	@Inject
	public SessionTracker(ConquestApiClient apiClient, OSRSConquestConfig config)
	{
		this.apiClient = apiClient;
		this.config = config;
	}

	public void onLogin(int world)
	{
		if (!config.trackSessions() || config.apiKey().isEmpty())
		{
			return;
		}

		sessionActive = true;
		apiClient.submitLogin(world);
		log.debug("Session started on world {}", world);
	}

	public void onLogout()
	{
		if (!config.trackSessions() || config.apiKey().isEmpty() || !sessionActive)
		{
			return;
		}

		sessionActive = false;
		apiClient.submitLogout();
		log.debug("Session ended");
	}

	public boolean isSessionActive()
	{
		return sessionActive;
	}
}

package net.osrsconquest;

import lombok.extern.slf4j.Slf4j;
import net.osrsconquest.model.ClanEvent;

import javax.inject.Singleton;
import java.time.Instant;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@Singleton
public class ClanEventParser
{
	// Member joined the clan
	private static final Pattern JOIN_PATTERN = Pattern.compile(
		"(.+) has been invited into the clan by (.+)\\."
	);

	// Member left the clan
	private static final Pattern LEAVE_PATTERN = Pattern.compile(
		"(.+) has left the clan\\."
	);

	// Member was kicked/expelled
	private static final Pattern KICK_PATTERN = Pattern.compile(
		"(.+) has been kicked from the clan by (.+)\\."
	);

	// Clan application: "<name> has applied to join the clan." or "<name> wishes to join the clan."
	private static final Pattern APPLICATION_PATTERN = Pattern.compile(
		"(.+) (?:has applied to join|wishes to join) (?:the|your) clan\\."
	);

	// Level up: "<name> has reached <skill> level <level>."
	// Also handles total level: "<name> has reached a total level of <level>."
	private static final Pattern LEVEL_UP_PATTERN = Pattern.compile(
		"(.+) has reached (.+) level (\\d+)\\."
	);
	private static final Pattern TOTAL_LEVEL_PATTERN = Pattern.compile(
		"(.+) has reached a total level of (\\d+)\\."
	);

	// Quest completion: "<name> has completed a quest: <quest name>"
	private static final Pattern QUEST_PATTERN = Pattern.compile(
		"(.+) has completed a quest: (.+)"
	);

	// Valuable drop: "<name> received a drop: <item> (<value>)"
	// or "<name> received a drop: <item>"
	private static final Pattern DROP_PATTERN = Pattern.compile(
		"(.+) received a drop: (.+?)(?:\\s*\\(([\\d,]+)\\s*coins\\))?$"
	);

	// Collection log: "<name> received a new collection log item: <item> (<count>)"
	private static final Pattern COLLECTION_LOG_PATTERN = Pattern.compile(
		"(.+) received a new collection log item: (.+?)(?:\\s*\\((\\d+)/(\\d+)\\))?$"
	);

	// Pet drop: "<name> has a funny feeling like .*"
	// or "<name> has a funny feeling like they would have been followed..."
	private static final Pattern PET_PATTERN = Pattern.compile(
		"(.+) (?:has a funny feeling like .+|feels something weird sneaking into .+)"
	);

	// Personal best: "<name> has achieved a new personal best: <boss/raid>"
	private static final Pattern PB_PATTERN = Pattern.compile(
		"(.+) has achieved a new (?:.*) personal best: (.+)"
	);

	// Rank change: "<name> has been promoted to <rank>." or "<name> has been demoted to <rank>."
	private static final Pattern RANK_CHANGE_PATTERN = Pattern.compile(
		"(.+) has been (promoted|demoted) (?:from .+ )?to (.+)\\."
	);

	// Diary completion
	private static final Pattern DIARY_PATTERN = Pattern.compile(
		"(.+) has completed the (.+)\\."
	);

	// Combat achievement
	private static final Pattern COMBAT_ACHIEVEMENT_PATTERN = Pattern.compile(
		"(.+) has completed an? (.+) combat task: (.+)\\."
	);

	public ClanEvent parse(String message)
	{
		// Strip any color tags and html from the message
		String clean = message
			.replaceAll("<[^>]+>", "")
			.replaceAll("\\u00a0", " ")
			.trim();

		Matcher m;

		// Join (invite)
		m = JOIN_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("JOIN")
				.target(m.group(1).trim())
				.actor(m.group(2).trim())
				.detail("Invited by " + m.group(2).trim())
				.timestamp(Instant.now().toString())
				.build();
		}

		// Leave
		m = LEAVE_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("LEAVE")
				.actor(m.group(1).trim())
				.timestamp(Instant.now().toString())
				.build();
		}

		// Kick
		m = KICK_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("KICK")
				.target(m.group(1).trim())
				.actor(m.group(2).trim())
				.timestamp(Instant.now().toString())
				.build();
		}

		// Application
		m = APPLICATION_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("APPLICATION")
				.actor(m.group(1).trim())
				.detail("Applied to join the clan")
				.timestamp(Instant.now().toString())
				.build();
		}

		// Total level
		m = TOTAL_LEVEL_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("LEVEL_UP")
				.actor(m.group(1).trim())
				.detail("Total level " + m.group(2).trim())
				.timestamp(Instant.now().toString())
				.build();
		}

		// Level up
		m = LEVEL_UP_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("LEVEL_UP")
				.actor(m.group(1).trim())
				.detail(m.group(2).trim() + " level " + m.group(3).trim())
				.timestamp(Instant.now().toString())
				.build();
		}

		// Quest
		m = QUEST_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("QUEST")
				.actor(m.group(1).trim())
				.detail(m.group(2).trim())
				.timestamp(Instant.now().toString())
				.build();
		}

		// Collection log
		m = COLLECTION_LOG_PATTERN.matcher(clean);
		if (m.matches())
		{
			String detail = m.group(2).trim();
			if (m.group(3) != null)
			{
				detail += " (" + m.group(3) + "/" + m.group(4) + ")";
			}
			return ClanEvent.builder()
				.type("COLLECTION_LOG")
				.actor(m.group(1).trim())
				.detail(detail)
				.timestamp(Instant.now().toString())
				.build();
		}

		// Drop
		m = DROP_PATTERN.matcher(clean);
		if (m.matches())
		{
			String detail = m.group(2).trim();
			if (m.group(3) != null)
			{
				detail += " (" + m.group(3) + " coins)";
			}
			return ClanEvent.builder()
				.type("DROP")
				.actor(m.group(1).trim())
				.detail(detail)
				.timestamp(Instant.now().toString())
				.build();
		}

		// Pet
		m = PET_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("PET")
				.actor(m.group(1).trim())
				.detail("Pet drop!")
				.timestamp(Instant.now().toString())
				.build();
		}

		// Personal best
		m = PB_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("PERSONAL_BEST")
				.actor(m.group(1).trim())
				.detail(m.group(2).trim())
				.timestamp(Instant.now().toString())
				.build();
		}

		// Rank change
		m = RANK_CHANGE_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("RANK_CHANGE")
				.actor(m.group(1).trim())
				.detail(m.group(2).trim() + " to " + m.group(3).trim())
				.timestamp(Instant.now().toString())
				.build();
		}

		// Combat achievement
		m = COMBAT_ACHIEVEMENT_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("COMBAT_ACHIEVEMENT")
				.actor(m.group(1).trim())
				.detail(m.group(2).trim() + ": " + m.group(3).trim())
				.timestamp(Instant.now().toString())
				.build();
		}

		// Diary
		m = DIARY_PATTERN.matcher(clean);
		if (m.matches())
		{
			return ClanEvent.builder()
				.type("DIARY")
				.actor(m.group(1).trim())
				.detail(m.group(2).trim())
				.timestamp(Instant.now().toString())
				.build();
		}

		// Unrecognized — log it for future pattern updates
		log.debug("Unrecognized clan message: {}", clean);
		return null;
	}
}

package net.osrsconquest;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("osrsconquest")
public interface OSRSConquestConfig extends Config
{
	@ConfigItem(
		keyName = "apiUrl",
		name = "API URL",
		description = "The OSRS Conquest backend API URL",
		position = 1
	)
	default String apiUrl()
	{
		return "https://conquest.projectonyx.net/api";
	}

	@ConfigItem(
		keyName = "apiKey",
		name = "API Key",
		description = "Your API key (auto-generated on first login)",
		secret = true,
		position = 2
	)
	default String apiKey()
	{
		return "";
	}

	@ConfigItem(
